import json
n=28
seps={4,9,14,19,24}
segments=[]
start=0
for i in range(n):
    if i in seps:
        if start<i: segments.append(list(range(start,i)))
        segments.append([i]); start=i+1
if start<n: segments.append(list(range(start,n)))
# Active panel color from aligned marker-to-marker straight connections; intersection is 6.
panel={}
# 3 joins the markers at panel (0,2) and (4,2).
for pr in range(5): panel[(pr,2)]=3
# 2 joins row 1, columns 0 through 4.
for pc in range(5): panel[(1,pc)]=2
# Crossing of the two strokes.
panel[(1,2)]=6
# Isolated 2 marker remains as a filled panel.
panel[(3,0)]=2
out=[[0]*n for _ in range(n)]
for r in seps:
    for c in range(n): out[r][c]=8
for c in seps:
    for r in range(n): out[r][c]=8
# Identify non-separator segment indices (panel rows/columns).
pranges=[s for s in segments if s[0] not in seps]
for (pr,pc),color in panel.items():
    for r in pranges[pr]:
        for c in pranges[pc]: out[r][c]=color
assert len(out)==28 and all(len(row)==28 for row in out)
assert all(set(row)<=set(range(10)) for row in out)
